<?php
require __DIR__.'/../vendor/autoload.php';
$app = require __DIR__.'/../bootstrap/app.php';
$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();

use App\Http\Controllers\{AdminController, BookingController, InstructorTimeSlotController, SessionCompletionController, SystemAdminController};
use App\Http\Requests\StoreSessionCompletionRequest;
use App\Models\{Admin, Booking, Course, EnrollmentRequest, Instructor, School, SessionCompletion, Student, TimeSlot};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{Auth, DB};
use Illuminate\Validation\ValidationException;

if (DB::connection()->getDatabaseName() !== 'drivingapp_regression_20261108') throw new RuntimeException('Run only in the isolated regression database.');
$checks = 0;
$check = function ($ok, $message) use (&$checks) { if (!$ok) throw new RuntimeException($message); ++$checks; echo "PASS: {$message}\n"; };
$request = function ($body, $method = 'POST', $class = Request::class) use ($app) {
    $r = $class::create('/qa', $method, $body, [], [], ['HTTP_ACCEPT' => 'application/json', 'HTTP_X_REQUESTED_WITH' => 'XMLHttpRequest']);
    $r->setLaravelSession(app('session')->driver()); $app->instance('request', $r); return $r;
};
$login = function ($guard, $user) { Auth::forgetGuards(); Auth::guard($guard)->setUser($user); };
$reject = function ($callback, $message) use ($check) { try { $callback(); } catch (ValidationException $e) { $check(true, $message); return; } throw new RuntimeException('Expected validation: '.$message); };
DB::beginTransaction();
try {
    $school = School::where('slug', 'drived-hub')->firstOrFail();
    app('session')->put('school_id', $school->id);
    $admin = Admin::where('school_id', $school->id)->where('role', 'school_admin')->firstOrFail();
    $instructor = Instructor::where('school_id', $school->id)->firstOrFail();
    $instructor->update(['license_status' => 'verified']);
    $student = Student::where('school_id', $school->id)->where('role', 'student')->firstOrFail();
    $course = Course::create(['school_id' => $school->id, 'title' => 'QA Nov8 Findings', 'course_type' => 'theoretical', 'type' => 'TDC', 'price' => 0, 'duration_hours' => 0, 'hours_required' => 0, 'status' => 'active']);
    $course->packages()->create(['name' => 'Manual', 'transmission_type' => 'manual', 'price' => 2301, 'training_hours' => 15]);
    $course->packages()->create(['name' => 'Automatic', 'transmission_type' => 'automatic', 'price' => 2600, 'training_hours' => 15]);
    $check($course->display_hours === '15', 'Zero base hours use package training hours');
    $check($course->display_price === '₱2,301.00–₱2,600.00', 'Course price displays the package range');
    $course->packages()->create(['name' => 'Extended', 'transmission_type' => 'manual', 'price' => 4000, 'training_hours' => 20]);
    $course->unsetRelation('packages');
    $check($course->display_hours === '15–20', 'Different package hours display a range');
    $login('admin', $admin);
    $body = ['date' => now()->addDays(10)->toDateString(), 'course_id' => $course->id, 'branch_id' => $admin->branch_id, 'max_instructors' => 4, 'max_students' => 20];
    $ranges = [['start_time' => '08:00', 'end_time' => '09:00'], ['start_time' => '13:00', 'end_time' => '15:00']];
    $result = app(AdminController::class)->createSchedule($request($body + ['time_ranges' => $ranges]), $school);
    $check($result->getStatusCode() === 201, 'Non-sequential same-day ranges create successfully');
    $check(TimeSlot::where('course_id', $course->id)->count() === 2, 'Both time ranges persist');
    $reject(fn () => app(AdminController::class)->createSchedule($request($body + ['time_ranges' => $ranges, 'batch_dates' => [now()->addDays(11)->toDateString()]]), $school), 'Same-day ranges and sequential dates cannot be combined');
    $reject(fn () => app(AdminController::class)->createSchedule($request($body + ['time_ranges' => [$ranges[0], ['start_time' => '08:30', 'end_time' => '10:00']]]), $school), 'Overlapping time ranges are rejected');
    $before = TimeSlot::where('course_id', $course->id)->count();
    $reject(fn () => app(AdminController::class)->createSchedule($request($body + ['time_ranges' => [$ranges[0], ['start_time' => '13:00', 'end_time' => '13:30']]]), $school), 'A short second range rejects the whole batch');
    $check(TimeSlot::where('course_id', $course->id)->count() === $before, 'Failed multi-range creation leaves no partial schedule');
    $course->update(['course_type' => 'practical']);
    $response = app(AdminController::class)->createSchedule($request(array_merge($body, ['date' => now()->addDays(100)->toDateString(), 'start_time' => '16:00', 'end_time' => '17:00', 'session_type' => 'practical'])), $school);
    $practical = TimeSlot::findOrFail($response->getData(true)['schedule']['id']);
    $check($practical->max_instructors === 4 && $practical->max_students === 1, 'Unassigned PDC retains configurable instructor capacity and one learner per instructor');
    $login('instructor', $instructor);
    $firstJoin = app(InstructorTimeSlotController::class)->toggle($school, $practical->id);
    $anotherInstructor = Instructor::where('school_id', $school->id)->whereKeyNot($instructor->id)->firstOrFail();
    $anotherInstructor->update(['license_status' => 'verified']);
    $login('instructor', $anotherInstructor);
    $secondJoin = app(InstructorTimeSlotController::class)->toggle($school, $practical->id);
    $check($firstJoin->getStatusCode() === 200 && $secondJoin->getStatusCode() === 200, 'Multiple instructors can join an initially unassigned PDC schedule');
    $check($practical->fresh()->instructors()->count() === 2 && $practical->fresh()->max_instructors === 4, 'PDC joins preserve the chosen capacity');
    $course->update(['course_type' => 'theoretical']);
    $slots = collect();
    for ($i = 0; $i < 3; $i++) $slots->push(TimeSlot::create(['school_id' => $school->id, 'course_id' => $course->id, 'date' => now()->addDays(15 + $i), 'start_time' => '09:00', 'end_time' => '10:00', 'session_type' => 'theoretical', 'status' => 'open', 'max_instructors' => 4, 'max_students' => 20, 'batch_group' => 'qa-nov8-batch', 'batch_day_number' => $i + 1]));
    $login('instructor', $instructor);
    $response = app(InstructorTimeSlotController::class)->selectBatch($request(['slot_ids' => $slots->pluck('id')->all()]), $school);
    $check($response->getStatusCode() === 200 && $slots->every(fn ($s) => $s->fresh()->hasInstructor($instructor->id)), 'Instructor selects every sequential batch day');
    $slots->each(fn ($s) => $s->instructors()->detach($instructor->id));
    $slots[1]->update(['status' => 'closed']);
    $reject(fn () => app(InstructorTimeSlotController::class)->selectBatch($request(['slot_ids' => $slots->take(2)->pluck('id')->all()]), $school), 'An unavailable day rejects instructor batch selection');
    $check(!$slots[0]->fresh()->hasInstructor($instructor->id), 'Instructor batch failure rolls back earlier assignments');
    $slots[1]->update(['status' => 'open']);
    foreach ($slots as $slot) $slot->instructors()->attach($instructor->id, ['school_id' => $school->id, 'assignment_type' => 'admin_assigned']);
    $enrollment = EnrollmentRequest::create(['school_id' => $school->id, 'learner_id' => $student->id, 'course_id' => $course->id, 'status' => 'approved', 'tdc_hours' => 15, 'pdc_hours' => 0, 'price' => 2301, 'branch_id' => $student->branch_id]);
    $school->schoolSetting->update(['booking_cutoff_hours' => 0, 'advance_booking_days' => 0]);
    $school->unsetRelation('schoolSetting');
    $login('student', $student);
    $bookingBody = ['slot_ids' => $slots->take(2)->pluck('id')->all(), 'enrollment_request_id' => $enrollment->id, 'instructor_id' => $instructor->id];
    $response = app(BookingController::class)->storeBatch($request($bookingBody), $school);
    $check($response->getStatusCode() === 201 && Booking::where('enrollment_request_id', $enrollment->id)->count() === 2, 'Student reserves selected days in one submission');
    $reject(fn () => app(BookingController::class)->storeBatch($request($bookingBody), $school), 'Student cannot reserve the same batch days twice');
    $check(Booking::where('enrollment_request_id', $enrollment->id)->count() === 2, 'Repeated batch creates no duplicate bookings');
    $closedDay = TimeSlot::create(['school_id' => $school->id, 'course_id' => $course->id, 'date' => now()->addDays(18), 'start_time' => '09:00', 'end_time' => '10:00', 'session_type' => 'theoretical', 'status' => 'closed', 'max_students' => 20, 'max_instructors' => 4, 'batch_group' => 'qa-nov8-batch', 'batch_day_number' => 4]);
    $reject(fn () => app(BookingController::class)->storeBatch($request(['slot_ids' => [$slots[2]->id, $closedDay->id], 'enrollment_request_id' => $enrollment->id, 'instructor_id' => $instructor->id]), $school), 'An unavailable second day rejects student batch booking');
    $check(!Booking::where('enrollment_request_id', $enrollment->id)->where('time_slot_id', $slots[2]->id)->exists(), 'Student batch failure rolls back the earlier reservation');
    $foreign = TimeSlot::create(['school_id' => $school->id, 'course_id' => $course->id, 'date' => now()->addDays(22), 'start_time' => '09:00', 'end_time' => '10:00', 'status' => 'open', 'batch_group' => 'other-group']);
    $reject(fn () => app(BookingController::class)->storeBatch($request(['slot_ids' => [$slots[2]->id, $foreign->id], 'enrollment_request_id' => $enrollment->id]), $school), 'Student cannot mix unrelated sequential batches');
    $login('instructor', $instructor);
    $sessionBody = ['enrollment_id' => $enrollment->id, 'session_type' => 'theoretical', 'hours_completed' => 1, 'session_date' => now()->subDays(100)->toDateString(), 'session_time' => '08:00', 'attendance_status' => 'attended'];
    $form = $request($sessionBody, 'POST', StoreSessionCompletionRequest::class);
    $validation = validator($form->all(), $form->rules());
    $check($validation->fails() && $validation->errors()->has('session_grade'), 'Attended sessions require a grade');
    $form = $request($sessionBody + ['session_grade' => 0], 'POST', StoreSessionCompletionRequest::class);
    $check(!validator($form->all(), $form->rules())->fails(), 'Zero is accepted as a real grade');
    $booking = Booking::create(['school_id' => $school->id, 'enrollment_request_id' => $enrollment->id, 'course_id' => $course->id, 'student_id' => $student->id, 'instructor_id' => $instructor->id, 'status' => 'scheduled', 'scheduled_at' => now()->subDays(100)->format('Y-m-d').' 08:00:00']);
    $response = app(SessionCompletionController::class)->store($school, $form);
    $check($response->getStatusCode() === 201, 'A graded manual session saves successfully');
    $session = SessionCompletion::findOrFail($response->getData(true)['session']['id']);
    $check($session->booking_id === $booking->id && (float) $session->session_grade === 0.0, 'Session persists grade and links its booking');
    $check($session->verification_status === 'Awaiting verification', 'New logs display awaiting admin verification');
    $booking->refresh()->update(['status' => 'completed']);
    $check($session->fresh()->verification_status === 'Verified', 'Admin completion displays verified status');
    $count = SessionCompletion::where('enrollment_id', $enrollment->id)->count();
    $reject(fn () => app(SessionCompletionController::class)->store($school, $form), 'Submitting the same session twice is rejected');
    $check(SessionCompletion::where('enrollment_id', $enrollment->id)->count() === $count, 'Duplicate submission leaves no extra session');
    $legacy = SessionCompletion::create(['school_id' => $school->id, 'enrollment_id' => $enrollment->id, 'instructor_id' => $instructor->id, 'session_type' => 'theoretical', 'session_date' => now()->subDays(101), 'session_time' => '08:00', 'hours_completed' => 1, 'session_grade' => 80, 'status' => 'completed']);
    $legacyForm = $request(array_merge($sessionBody, ['session_date' => now()->subDays(101)->toDateString(), 'session_grade' => 80]), 'POST', StoreSessionCompletionRequest::class);
    $reject(fn () => app(SessionCompletionController::class)->store($school, $legacyForm), 'Legacy sessions without start_time also reject duplicate date and time');
    $response = app(InstructorTimeSlotController::class)->updateLessonDetails($school, $slots[2]->bookings()->first() ?? $booking, $request(['session_status' => 'done', 'attendance_status' => 'attended', 'session_grade' => 75]));
    $check($response->getStatusCode() === 200, 'Existing graded schedule feedback remains editable');
    $reject(fn () => app(InstructorTimeSlotController::class)->updateLessonDetails($school, $booking->fresh(), $request(['session_status' => 'done', 'attendance_status' => 'attended', 'session_grade' => null])), 'An attended session cannot clear an existing grade');
    $login('admin', Admin::where('role', 'system_admin')->firstOrFail());
    $history = Booking::where('student_id', $student->id)->count();
    $reject(fn () => app(SystemAdminController::class)->deleteUser($request(['confirmation' => 'delete wrong name'], 'DELETE'), 'student', $student->id), 'Account removal requires the exact typed name');
    $check($student->fresh()->archived_at === null, 'Wrong confirmation leaves account active');
    app(SystemAdminController::class)->deleteUser($request(['confirmation' => 'delete '.$student->name], 'DELETE'), 'student', $student->id);
    $check($student->fresh()->status === 'archived', 'Confirmed user removal archives the account');
    $check(Booking::where('student_id', $student->id)->count() === $history && $enrollment->fresh() !== null, 'Archiving preserves bookings and enrollment history');
    echo "RESULT: {$checks} assertions passed.\n";
} finally {
    while (DB::transactionLevel() > 0) DB::rollBack();
}
